import { useState, useEffect } from 'react';
import { Package, Truck, AlertCircle, Loader2, Leaf } from 'lucide-react';
import api from '../lib/axios';
import { format } from 'date-fns';

const getStatusBadge = (status) => {
  switch (status) {
    case 'Pending':
      return 'bg-orange-100 text-orange-800 border-orange-200';
    case 'Confirmed':
      return 'bg-green-100 text-green-800 border-green-200';
    case 'In Transit':
      return 'bg-blue-100 text-blue-800 border-blue-200';
    case 'Delivered':
      return 'bg-gray-100 text-gray-800 border-gray-200';
    default:
      return 'bg-gray-100 text-gray-800 border-gray-200';
  }
};

export const Orders = () => {
  const [orders, setOrders] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchMyOrders = async () => {
      try {
        const { data } = await api.get('/orders/myorders');
        setOrders(data);
      } catch (err) {
        setError('Failed to load your order history.');
      } finally {
        setIsLoading(false);
      }
    };

    fetchMyOrders();
  }, []);

  return (
    <div className="space-y-6 max-w-6xl mx-auto">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold text-gray-900">My Orders</h2>
          <p className="text-sm text-gray-500">Track and manage your produce purchases.</p>
        </div>
      </div>

      {error && (
        <div className="p-4 bg-red-50 text-red-700 rounded-xl flex items-center gap-3 border border-red-200">
          <AlertCircle size={20} />
          <span className="font-medium">{error}</span>
        </div>
      )}

      {isLoading ? (
        <div className="flex flex-col items-center justify-center py-20 text-gray-400">
          <Loader2 className="animate-spin mb-4 text-farmGreen" size={40} />
          <p className="font-medium">Loading orders...</p>
        </div>
      ) : orders.length === 0 ? (
        <div className="text-center py-20 bg-white rounded-xl border border-gray-200 shadow-sm">
          <Package className="mx-auto text-gray-300 mb-3" size={48} />
          <h3 className="text-lg font-bold text-gray-900">No Orders Yet</h3>
          <p className="text-gray-500">You haven't placed any produce requests.</p>
        </div>
      ) : (
        <div className="bg-white border border-gray-200 rounded-xl shadow-sm overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full text-left border-collapse">
              <thead>
                <tr className="bg-gray-50 border-b border-gray-200 text-sm text-gray-500">
                  <th className="p-4 font-semibold">Order ID & Date</th>
                  <th className="p-4 font-semibold">Produce Details</th>
                  <th className="p-4 font-semibold">Route</th>
                  <th className="p-4 font-semibold">Total Price</th>
                  <th className="p-4 font-semibold">Status</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-100">
                {orders.map((order) => (
                  <tr key={order._id} className="hover:bg-gray-50/50 transition-colors">
                    
                    {/* ID & Date */}
                    <td className="p-4">
                      <p className="text-sm font-bold text-gray-900 uppercase">
                        {/* Trim the MongoDB ID just for display purposes */}
                        ORD-{order._id.slice(-6)} 
                      </p>
                      <p className="text-xs text-gray-500 mt-0.5">
                        {format(new Date(order.createdAt), 'dd MMM yyyy')}
                      </p>
                    </td>

                    {/* Produce Details */}
                    <td className="p-4">
                      <div className="flex items-center gap-3">
                        <div className="w-10 h-10 rounded bg-farmGreen/10 flex items-center justify-center text-farmGreen">
                          <Leaf size={20} />
                        </div>
                        <div>
                          <p className="text-sm font-bold text-gray-900">
                            {order.produceItem?.cropType || 'Deleted Item'}
                          </p>
                          <p className="text-xs text-gray-500">{order.quantityKg} kg requested</p>
                        </div>
                      </div>
                    </td>

                    {/* Route (Location -> Delivery) */}
                    <td className="p-4">
                      <div className="flex flex-col gap-1">
                        <p className="text-xs font-medium text-gray-500 truncate max-w-[150px]">
                          From: <span className="text-gray-900">{order.produceItem?.location || 'Unknown'}</span>
                        </p>
                        <p className="text-xs font-medium text-gray-500 truncate max-w-[150px]">
                          To: <span className="text-gray-900">{order.deliveryLocation}</span>
                        </p>
                      </div>
                    </td>

                    {/* Price */}
                    <td className="p-4">
                      <p className="text-sm font-bold text-gray-900">GHS {order.totalPrice.toFixed(2)}</p>
                      <p className="text-xs text-gray-500">{order.paymentMethod}</p>
                    </td>

                    {/* Status */}
                    <td className="p-4">
                      <span className={`px-3 py-1 text-xs font-bold rounded-full border inline-flex items-center gap-1.5 ${getStatusBadge(order.status)}`}>
                        {order.status === 'In Transit' && <Truck size={12} />}
                        {order.status}
                      </span>
                    </td>

                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  );
};
